import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for sqlite3 import
found_sqlite = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'sqlite3' for name in node.names):
        found_sqlite = True

if not found_sqlite:
    raise AssertionError('Task 1: Missing import sqlite3')

# Check for with statement
found_with = False
for node in ast.walk(tree):
    if isinstance(node, ast.With):
        found_with = True

if not found_with:
    raise AssertionError('Task 1: Missing with statement for database connection')

# Check for CREATE TABLE statement
found_create = False
code_str = user_code.upper()
if 'CREATE TABLE IF NOT EXISTS PRODUCTS' in code_str:
    found_create = True

if not found_create:
    raise AssertionError('Task 2: Missing CREATE TABLE IF NOT EXISTS statement')

# Check for executemany() with sample data
found_executemany = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'executemany':
        found_executemany = True

if not found_executemany:
    raise AssertionError('Task 3: Missing executemany() call')

# Check for SELECT statements
select_count = 0
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'execute':
        if node.args:
            # Check if first argument contains SELECT (could be string or variable)
            first_arg = node.args[0]
            if isinstance(first_arg, ast.Constant) and 'SELECT' in str(first_arg.value).upper():
                select_count += 1
            elif isinstance(first_arg, ast.Name):
                # If it's a variable, we can't check content, but assume it's a SELECT
                select_count += 1

if select_count < 4:
    raise AssertionError('Tasks 4-7: Missing required SELECT statements')

# Check for UPDATE statements (more flexible validation)
update_count = 0
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'execute':
        if node.args:
            first_arg = node.args[0]
            # Check if first argument contains UPDATE (could be string or variable)
            if isinstance(first_arg, ast.Constant) and 'UPDATE' in str(first_arg.value).upper():
                update_count += 1
            elif isinstance(first_arg, ast.Name):
                # If it's a variable, count it as an UPDATE (we trust student)
                # This handles the case where SQL is stored in a variable
                update_count += 1

if update_count < 2:
    raise AssertionError('Tasks 8-9: Missing UPDATE statements')

# Check for DELETE statement
found_delete = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'execute':
        if node.args:
            first_arg = node.args[0]
            # Check if first argument contains DELETE
            if isinstance(first_arg, ast.Constant) and 'DELETE' in str(first_arg.value).upper():
                found_delete = True
            elif isinstance(first_arg, ast.Name):
                # If it's a variable, count it as a DELETE
                found_delete = True

if not found_delete:
    raise AssertionError('Task 10: Missing DELETE statement')

# Check for commit calls
commit_count = 0
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'commit':
        commit_count += 1

if commit_count < 4:
    raise AssertionError('Missing commit() calls - remember to commit after changes!')

print('TEST_PASSED')
